select
a.*,a.produce_Unity_No as batch
from ${tableName} a
where
a.enterprise_code = #{enterpriseCode}
AND a.delete_flag = false

    AND a.batch_num like concat('%', #{data.batchNum}, '%')


    AND a.product_or_part_name like concat('%',#{data.productName}, '%')


    AND a.procedure_name like concat('%',#{data.gxName}, '%')



    AND a.product_Flag =#{data.productFlag}




    AND a.Procedure_Flag = #{data.gxCondition}




    AND exists( select * from ${productPart} b where a.product_or_part=b.primary_key and b.model like '%'||
    #{data.model}|| '%' )



    AND exists(select *
    from ${productPart} b
    where a.product_or_part = b.primary_key
    and b.primary_key = #{data.productPartCode})



    AND exists(select *
    from ${productPart} b
    where a.product_or_part = b.primary_key
    and b.primary_key in

        #{item}

    )



    AND (a.buss_Number like '%'|| #{data.bussNumber}|| '%'




        or exists( select 1 from ${dynamicTableNameProxy.produceSubDispatcher} dd where dd.main_id=a.primary_key and dd.produce_Unity_No like
        concat('%',#{data.bussNumber}, '%') )



    )





    AND a.status = #{data.status}



    AND a.delivery_Date >= #{data.beginDate}



    AND a.contract_code = #{data.contractCode}



    AND a.primary_key = #{data.mainId}



    AND a.delivery_Date <= #{data.endDate}



    AND a.batch_Global_Code = #{data.batchGlobalCode}




    AND exists (

    select 1 from (
    select * , ROW_NUMBER() OVER ( order by create_time desc NULLS last ) mid
    from ${produceSubDispatcher} b
    where b.operator=#{data.operatorId} and b.main_id=a.primary_key
    ) b


        where b.mid=1 AND b.status = #{data.status}

    )




        AND exists (

        select 1 from (
        select * , ROW_NUMBER() OVER ( order by finish_date desc NULLS last ) mid
        from ${produceSubDispatcher} b
        where b.operator=#{data.operatorId} and b.main_id=a.primary_key
        ) b

        where b.mid=1

            AND b.finish_date >= DATE(#{data.beginDate})



            AND b.finish_date <= DATE(#{data.endDate})


        )







    AND a.status in

        #{status}






    AND exists ( select 1 from ${produceSubDispatcher} b
    ,${staff} c
    where b.main_id=a.primary_key
    and c.primary_key =b.operator and c.staff_sign like concat('%',#{data.operatorName}, '%')
    )



    and ${dynamicTableNameProxy.getXiHangPartQuery("a.product_or_part","xihang",data.partUnityNo)}

and ${dynamicTableNameProxy.getProductPartSearchObj("a.product_or_part",data.searchName)}

order by create_time desc ,id desc

