with source as (
select b.main_id ,b."operator" ,sum( b.allocation_Num ) a_sum ,max(b.finish_date) finishDate ,max(c.staff_sign)
operator_name
,max(b.remark) remark
from ${produceSubDispatcher} b ,${staff} c
where b."operator" is not null and c.primary_key =b.operator

    and c.staff_sign like concat('%',#{data.operatorName}, '%')


AND b.delete_flag = false
and b.enterprise_code=${dynamicTableNameProxy.enterpriseCode}


    and b.operator=#{data.operatorId}

        AND b.status = #{data.status}






    AND exists (

    select 1 from (
    select * , ROW_NUMBER() OVER ( order by finish_date desc NULLS last ) mid
    from ${produceSubDispatcher} s
    where s.operator=b."operator" and s.main_id=b.main_id
    ) s

    where s.mid=1

        AND s.finish_date >= DATE(#{data.beginDate})



        AND s.finish_date <= DATE(#{data.endDate})


    )





group by b.main_id ,b."operator"
),
ostatus as (

select * from ${produceSubDispatcher} aa where (main_id , "operator" , id ) in (

select * from (select a.main_id ,a."operator" , max(id) max_id from ${produceSubDispatcher} a , source b where
b.main_id=a.main_id and b."operator"=a."operator"
group by a.main_id ,a."operator"
) as a )

AND aa.delete_flag = false
and aa.enterprise_code=${dynamicTableNameProxy.enterpriseCode}

    AND aa.status = #{data.status}

)

select b.* ,a.*, a.produce_Unity_No as batch,c.status ,c.status status_real ,c.main_id || '-' ||c."operator" as queryKey from source b ,${tableName} a ,
ostatus c where
b.main_id=a.primary_key

AND a.delete_flag = false
and a.enterprise_code=${dynamicTableNameProxy.enterpriseCode}

and b.main_id=c.main_id and b."operator"=c."operator"


    AND a.batch_num like concat('%', #{data.batchNum}, '%')




    AND (a.buss_Number like '%'|| #{data.bussNumber}|| '%'



        or exists( select 1 from ${dynamicTableNameProxy.produceSubDispatcher} dd where dd.main_id=a.primary_key and dd.produce_Unity_No like
        concat('%',#{data.bussNumber}, '%') )


    )







    AND a.product_Flag =#{data.productFlag}




    AND a.product_or_part_name like concat('%',#{data.productName}, '%')


    AND a.procedure_name like concat('%',#{data.gxName}, '%')



    AND a.status = #{data.status}



    AND a.contract_code = #{data.contractCode}



    and DATE_TRUNC('day', now()) <= b.finishDate + interval ' 1 days'*#{data.days} and DATE_TRUNC('day',
    now()) >= b.finishDate
    and a_sum > (
    select sum(finish_num) from ${reportTableName} d
    where b.operator=d.creator and b.main_id=d.main_id
    )



    and ${dynamicTableNameProxy.getXiHangPartQuery("a.product_or_part","xihang",data.partUnityNo)}


and ${dynamicTableNameProxy.getProductPartSearchObj("a.product_or_part",data.searchName)}
order by a.create_time desc , id desc

